package org.citydb.database.geometry;

import org.citydb.model.geometry.*;
import org.junit.jupiter.api.Test;

import java.util.HexFormat;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class WKBTest {
    private static final String POINT_2D = "010100000000000000000024400000000000003440";
    private static final String POINT_3D = "0101000080000000000000244000000000000034400000000000003E40";
    private static final String MULTIPOINT_3D = "0104000080020000000101000080000000000000244000000000000034400000000000003E400101000080000000000000264000000000000035400000000000003F40";
    private static final String LINESTRING_3D = "010200008002000000000000000000244000000000000034400000000000003E40000000000000264000000000000035400000000000003F40";
    private static final String MULTILINESTRING_3D = "010500008002000000010200008002000000000000000000244000000000000034400000000000003E40000000000000264000000000000035400000000000003F40010200008002000000000000000000F03F00000000000000400000000000000840000000000000004000000000000008400000000000001040";
    private static final String POLYGON_3D = "01030000800100000004000000000000000000244000000000000034400000000000003E40000000000000264000000000000035400000000000003F40000000000000284000000000000036400000000000004040000000000000244000000000000034400000000000003E40";
    private static final String POLYGON_3D_HOLE = "";
    private static final String MULTIPOLYGON_3D = "";
    private static final String POLYHEDRALSURFACE_3D = "";
    private static final String GEOMETRYCOLLECTION_3D = "";

    private final WKBParser parser = new WKBParser();
    private final WKBWriter writer = new WKBWriter();

    @Test
    void roundTripsGeometries() throws GeometryException {
        for (String wkb : List.of(POINT_2D, POINT_3D, MULTIPOINT_3D, LINESTRING_3D, MULTILINESTRING_3D,
                POLYGON_3D, POLYGON_3D_HOLE, MULTIPOLYGON_3D)) {
            assertEquals(wkb, writer.write(parser.parse(wkb)), wkb);
        }
    }

    @Test
    void roundTripsPolyhedralSurface() throws GeometryException {
        Solid solid = assertInstanceOf(Solid.class, parser.parse(POLYHEDRALSURFACE_3D));
        assertEquals(POLYHEDRALSURFACE_3D, writer.write(Solid.of(solid.getShell())));
    }

    @Test
    void parsesGeometryCollectionOfPolyhedralSurfacesAsMultiSolid() throws GeometryException {
        MultiSolid multiSolid = assertInstanceOf(MultiSolid.class, parser.parse(GEOMETRYCOLLECTION_3D));
        assertEquals(3, multiSolid.getVertexDimension());
        assertEquals(2, multiSolid.getSolids().size());
    }

    @Test
    void writesGeometryCollection() {
        GeometryCollection collection = GeometryCollection.of(List.of(Point.of(Coordinate.of(1, 2))));

        // little endian, type 7 (geometry collection), 1 member: point (1 2)
        assertEquals("0107000000010000000101000000000000000000F03F0000000000000040", writer.write(collection));
    }

    @Test
    void writesEmptyGeometryCollection() {
        // little endian, type 7 (geometry collection) with Z flag, 0 members
        assertEquals("010700008000000000",writer.write(GeometryCollection.of(List.of())));
    }

    @Test
    void writesBinaryLikeHex() {
        GeometryCollection collection = GeometryCollection.of(List.of(
                Point.of(Coordinate.of(1, 2)),
                LineString.of(List.of(Coordinate.of(0, 0), Coordinate.of(1, 1))))).setSRID(4326);
        WKBWriter writer = new WKBWriter().includeSRID(true);

        assertEquals(writer.write(collection), HexFormat.of().withUpperCase().formatHex(writer.writeBinary(collection)));
    }
}
